html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}

{% if letter_head and not no_letterhead %}

<div class="letter-head">{{ letter_head }}</div>
{% endif %}

{% if print_heading_template %}
{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
{% endif %}

{%- endmacro -%}

{% for page in layout %}

<div class="page-break">

<div {% if print_settings.repeat_header_footer %}id="header-html" class="hidden-pdf"{% endif %}>
    {{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
</div>


<style>

    /* =========================
       BASIC
    ========================= */

    .po-page {
        font-family: Arial, Helvetica, sans-serif;
        font-size: 12px;
        color: #222;
        line-height: 1.45;
    }

    .po-page table {
        width: 100%;
        border-collapse: collapse;
    }

    .po-page td {
        padding: 7px 8px;
        vertical-align: top;
    }

    .label {
        font-weight: 600;
        color: #444;
    }

    .value {
        color: #222;
    }

    .section-title {
        font-size: 14px;
        font-weight: 700;
        margin: 12px 0 7px 0;
    }

    .text-left {
        text-align: left;
    }

    .text-center {
        text-align: center;
    }

    .text-right {
        text-align: right;
    }


    /* =========================
       LETTER HEAD
    ========================= */

    .letter-head {
        padding-top: 6px !important;
        padding-bottom: 10px !important;
    }


    /* =========================
       BILINGUAL LABELS
    ========================= */

    .bilingual-label {
        line-height: 1.25;
    }

    .bilingual-label .english-label {
        display: block;
        font-size: 11px;
        font-weight: 700;
        color: #444;
        line-height: 1.25;
    }

    .bilingual-label .arabic-label {
        display: block;
        direction: rtl;
        unicode-bidi: embed;
        font-size: 12px;
        font-weight: 600;
        color: #222;
        margin-top: 2px;
        line-height: 1.35;
        font-family: Arial, Tahoma, sans-serif;
    }


    /* =========================
       DOCUMENT INFO
    ========================= */

    .info-table {
        border: 1px solid #555;
        margin-top: 6px;
    }

    .info-table td {
        border: 1px solid #555;
        font-size: 12px;
        padding: 7px 8px;
    }

    .info-label {
        width: 15%;
        font-weight: 700;
        background: #f5f5f5;
    }

    .info-value {
        width: 35%;
        font-size: 12px;
    }


    /* =========================
       INTRODUCTION
    ========================= */

    .intro-text {
        margin: 10px 0;
        font-size: 12px;
        font-weight: 600;
    }


    /* =========================
       ITEMS
    ========================= */

    .items-table {
        margin-top: 8px;
        border: 1px solid #555;
    }

    .items-table th {
        background: #f3f3f3;
        border: 1px solid #555;
        padding: 7px 7px;
        font-size: 11px;
        font-weight: 700;
        vertical-align: middle;
    }

    .items-table td {
        border: 1px solid #ccc;
        padding: 7px 7px;
        font-size: 12px;
    }


    /* =========================
       TOTALS
    ========================= */

    .totals-wrapper {
        margin-top: 10px;
    }

    .totals-table {
        width: 48%;
        margin-left: auto;
    }

    .totals-table td {
        padding: 6px 8px;
        border-bottom: 1px solid #ddd;
        font-size: 12px;
    }

    .total-label {
        text-align: right;
        color: #555;
    }

    .grand-total {
        font-weight: 700;
        font-size: 13px !important;
    }


    /* =========================
       AMOUNT IN WORDS
    ========================= */

    .words-table {
        margin-top: 7px;
        background: #f7f7f7;
        border: 1px solid #ddd;
    }

    .words-table td {
        padding: 7px 8px;
        font-size: 12px;
    }

    .words-label {
        width: 15%;
        font-weight: 700;
    }


    /* =========================
       EXCHANGE RATE
    ========================= */

    .exchange-rate {
        margin-top: 10px;
        border-top: 1px solid #555;
        border-bottom: 1px solid #555;
        padding: 7px 5px;
        font-size: 12px;
    }

    .exchange-title {
        font-weight: 700;
        font-size: 12px;
    }


    /* =========================
       ADDITIONAL INFORMATION
    ========================= */

    .details-table {
        margin-top: 10px;
        border: 1px solid #ccc;
    }

    .details-table td {
        border: 1px solid #ccc;
        padding: 7px 8px;
        font-size: 12px;
    }

    .details-label {
        width: 18%;
        font-weight: 700;
        background: #f7f7f7;
    }

    .details-value {
        width: 32%;
    }


    /* =========================
       TERMS
    ========================= */

    .terms {
        margin-top: 12px;
        font-size: 12px;
    }

    .terms-title {
        font-weight: 700;
        font-size: 13px;
        margin-bottom: 5px;
    }


    /* =========================
       APPROVAL
    ========================= */

    .approval {
        margin-top: 18px;
        border-top: 1px solid #555;
        padding-top: 12px;
    }

    .approval-signatures {
        display: flex;
        justify-content: flex-start;
        align-items: flex-start;
        gap: 55px;
        width: 100%;
        margin-bottom: 12px;
    }

    .approval-signature {
        width: 150px;
        text-align: center;
        vertical-align: bottom;
    }

    .approval-signature-image {
        height: 55px;
        display: flex;
        align-items: flex-end;
        justify-content: center;
        margin-bottom: 6px;
    }

    .approval-signature-image img {
        max-width: 140px;
        max-height: 50px;
        object-fit: contain;
    }

    .approval-user-name {
        font-size: 12px;
        font-weight: 700;
        color: #222;
        border-top: 1px solid #777;
        padding-top: 5px;
    }

    .approval-user-email {
        font-size: 10px;
        color: #666;
        margin-top: 2px;
        word-break: break-word;
    }

    .approval-title {
        font-size: 14px;
        font-weight: 700;
        text-align: left;
        margin-top: 8px;
    }


    /* =========================
       FOOTER
    ========================= */

    .letter-head-footer {
        margin-top: 5px !important;
    }

    .page-number {
        font-size: 10px;
    }

</style>


<div class="po-page">


    <!-- =========================
         STATUS
    ========================== -->

    {% if doc.meta.is_submittable and doc.docstatus == 2 %}

    <div class="text-center">
        <b>{{ doc.doctype }}</b><br>
        <b>CANCELLED</b>
    </div>

    {% endif %}


    {% if doc.meta.is_submittable and doc.docstatus == 0 and (print_settings == None or print_settings.add_draft_heading) %}

    <div class="text-center">
        <b>{{ doc.doctype }}</b><br>
        <b>DRAFT</b>
    </div>

    {% endif %}


    <!-- =========================
         SUPPLIER / PO DETAILS
    ========================== -->

    <table class="info-table">

        <tr>

            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Order To") }}
                </span>
                <span class="arabic-label">
                    إلى المورد
                </span>
            </td>

            <td class="info-value">
                {{ doc.supplier_name or '' }}
            </td>


            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Purchase Order") }}
                </span>
                <span class="arabic-label">
                    أمر الشراء
                </span>
            </td>

            <td class="info-value">
                {{ doc.name or '' }}
            </td>

        </tr>


        <tr>

            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Attention To") }}
                </span>
                <span class="arabic-label">
                    عناية
                </span>
            </td>

            <td class="info-value">
                {{ doc.address_display or '' }}
            </td>


            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Purchase Order Date") }}
                </span>
                <span class="arabic-label">
                    تاريخ أمر الشراء
                </span>
            </td>

            <td class="info-value">
                {{ frappe.utils.format_date(doc.transaction_date) }}
            </td>

        </tr>


        <tr>

            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Project Name") }}
                </span>
                <span class="arabic-label">
                    اسم المشروع
                </span>
            </td>

            <td class="info-value">
                {{ doc.project or '' }}
            </td>


            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Purchase Type / Mode") }}
                </span>
                <span class="arabic-label">
                    نوع / طريقة الشراء
                </span>
            </td>

            <td class="info-value">
                {{ doc.custom_purchase_type or '' }}
            </td>

        </tr>


        <tr>

            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Incoterms") }}
                </span>
                <span class="arabic-label">
                    شروط التجارة الدولية
                </span>
            </td>

            <td class="info-value">
                {{ doc.incoterm or '' }}
            </td>


            <td class="info-label bilingual-label">
                <span class="english-label">
                    {{ _("Required By") }}
                </span>
                <span class="arabic-label">
                    مطلوب بحلول
                </span>
            </td>

            <td class="info-value">
                {{ frappe.utils.format_date(doc.schedule_date) if doc.schedule_date else '' }}
            </td>

        </tr>

    </table>


    <!-- =========================
         INTRODUCTION
    ========================== -->

    <div class="intro-text">

        This Purchase Order is issued for you to proceed with the supply,
        provision of documentation and delivery of the following.

    </div>


    <!-- =========================
         ITEMS
    ========================== -->

    <table class="items-table">

        <thead>

            <tr>

                <th style="width: 6%;" class="text-center bilingual-label">

                    <span class="english-label">
                        {{ _("No") }}
                    </span>

                    <span class="arabic-label">
                        الرقم
                    </span>

                </th>


                <th style="width: 18%;" class="text-left bilingual-label">

                    <span class="english-label">
                        {{ _("Item Code") }}
                    </span>

                    <span class="arabic-label">
                        رمز الصنف
                    </span>

                </th>


                <th style="width: 32%;" class="text-left bilingual-label">

                    <span class="english-label">
                        {{ _("Item Name") }}
                    </span>

                    <span class="arabic-label">
                        اسم الصنف
                    </span>

                </th>


                <th style="width: 14%;" class="text-right bilingual-label">

                    <span class="english-label">
                        {{ _("Quantity") }}
                    </span>

                    <span class="arabic-label">
                        الكمية
                    </span>

                </th>


                <th style="width: 15%;" class="text-right bilingual-label">

                    <span class="english-label">
                        {{ _("Rate") }}
                    </span>

                    <span class="arabic-label">
                        السعر
                    </span>

                </th>


                <th style="width: 15%;" class="text-right bilingual-label">

                    <span class="english-label">
                        {{ _("Amount") }}
                    </span>

                    <span class="arabic-label">
                        المبلغ
                    </span>

                </th>

            </tr>

        </thead>


        <tbody>

            {% for item in doc.items %}

            <tr>

                <td class="text-center">
                    {{ loop.index }}
                </td>

                <td>
                    {{ item.item_code or '' }}
                </td>

                <td>
                    {{ item.item_name or '' }}
                </td>

                <td class="text-right">
                    {{ item.get_formatted("qty", 0) }}
                    {{ item.uom or '' }}
                </td>

                <td class="text-right">
                    {{ item.get_formatted("net_rate", doc) }}
                </td>

                <td class="text-right">
                    {{ item.get_formatted("net_amount", doc) }}
                </td>

            </tr>

            {% endfor %}

        </tbody>

    </table>


    <!-- =========================
         TOTALS
    ========================== -->

    <div class="totals-wrapper">

        <table class="totals-table">

            <tr>

                <td class="total-label bilingual-label">

                    <span class="english-label">
                        {{ _("Sub Total") }}
                    </span>

                    <span class="arabic-label">
                        المجموع الفرعي
                    </span>

                </td>

                <td class="text-right">
                    {{ doc.get_formatted("total", doc) }}
                </td>

            </tr>


            {% if doc.apply_discount_on == "Net Total" %}

            <tr>

                <td class="total-label bilingual-label">

                    <span class="english-label">
                        {{ _("Discount") }}
                        ({{ doc.additional_discount_percentage }}%)
                    </span>

                    <span class="arabic-label">
                        الخصم
                    </span>

                </td>

                <td class="text-right">
                    {{ doc.get_formatted("discount_amount", doc) }}
                </td>

            </tr>

            {% endif %}


            {% for tax in doc.taxes %}

            {% if (tax.tax_amount or print_settings.print_taxes_with_zero_amount)
                and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) %}

            <tr>

                <td class="total-label bilingual-label">

                    <span class="english-label">
                        {{ tax.get_formatted("description") }}
                        ({{ tax.get_formatted("rate") }}%)
                    </span>

                    <span class="arabic-label">
                        الضريبة
                    </span>

                </td>

                <td class="text-right">
                    {{ tax.get_formatted("tax_amount") }}
                </td>

            </tr>

            {% endif %}

            {% endfor %}


            {% if doc.apply_discount_on == "Grand Total" %}

            <tr>

                <td class="total-label bilingual-label">

                    <span class="english-label">
                        {{ _("Discount") }}
                        ({{ doc.additional_discount_percentage }}%)
                    </span>

                    <span class="arabic-label">
                        الخصم
                    </span>

                </td>

                <td class="text-right">
                    {{ doc.get_formatted("discount_amount", doc) }}
                </td>

            </tr>

            {% endif %}


            <tr>

                <td class="total-label grand-total bilingual-label">

                    <span class="english-label">
                        {{ _("Grand Total") }}
                    </span>

                    <span class="arabic-label">
                        الإجمالي الكلي
                    </span>

                </td>

                <td class="text-right grand-total">
                    {{ doc.get_formatted("grand_total", doc) }}
                </td>

            </tr>

        </table>

    </div>


    <!-- =========================
         AMOUNT IN WORDS
    ========================== -->

    <table class="words-table">

        <tr>

            <td class="words-label bilingual-label">

                <span class="english-label">
                    {{ _("Amount in Words") }}
                </span>

                <span class="arabic-label">
                    المبلغ بالكلمات
                </span>

            </td>

            <td>
                {{ doc.in_words or '' }}
            </td>

        </tr>

    </table>


    <!-- =========================
         EXCHANGE RATE
    ========================== -->

    <div class="exchange-rate">

        <span class="exchange-title">
            {{ _("Applied Rates of Exchange") }}
        </span>

        <span class="arabic-label"
              style="display:inline-block; margin-left:8px;">
            أسعار الصرف المطبقة
        </span>

        <span>
            :
            {{ doc.currency }} @ {{ doc.conversion_rate or 1.0000 }}
        </span>

    </div>


    <!-- =========================
         ADDITIONAL INFORMATION
    ========================== -->

    <table class="details-table">

        <tr>

            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Consignee") }}
                </span>

                <span class="arabic-label">
                    المرسل إليه
                </span>

            </td>

            <td class="details-value">
                {{ doc.shipping_address or '' }}<br>
                {{ doc.shipping_address_display or '' }}
            </td>


            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Payment Terms") }}
                </span>

                <span class="arabic-label">
                    شروط الدفع
                </span>

            </td>

            <td class="details-value">
                {{ doc.payment_terms_template or '' }}
            </td>

        </tr>


        <tr>

            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Origin Country") }}
                </span>

                <span class="arabic-label">
                    بلد المنشأ
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_origin_country or '' }}
            </td>


            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Export Documentation") }}
                </span>

                <span class="arabic-label">
                    مستندات التصدير
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_export_documentation or '' }}
            </td>

        </tr>


        <tr>

            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Technical Documentation") }}
                </span>

                <span class="arabic-label">
                    المستندات الفنية
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_technical_documentation or '' }}
            </td>


            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Insurance") }}
                </span>

                <span class="arabic-label">
                    التأمين
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_insurance or '' }}
            </td>

        </tr>


        <tr>

            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Country of Origin Documentation") }}
                </span>

                <span class="arabic-label">
                    مستندات بلد المنشأ
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_country_of_origin_documentation or '' }}
            </td>


            <td class="details-label bilingual-label">

                <span class="english-label">
                    {{ _("Shipping Marks") }}
                </span>

                <span class="arabic-label">
                    علامات الشحن
                </span>

            </td>

            <td class="details-value">
                {{ doc.custom_shipping_marks or '' }}
            </td>

        </tr>

    </table>


    <!-- =========================
         TERMS
    ========================== -->

    {% if doc.terms %}

    <div class="terms">

        <div class="terms-title bilingual-label">

            <span class="english-label">
                {{ _("Terms and Conditions") }}
            </span>

            <span class="arabic-label">
                الشروط والأحكام
            </span>

        </div>

        <div>
            {{ doc.terms }}
        </div>

    </div>

    {% endif %}


    <!-- =========================
         APPROVAL
    ========================== -->

    <div class="approval">

        {% set all_approval = frappe.get_all(
            "Comment",
            filters={
                "comment_type": "Workflow",
                "reference_doctype": "Purchase Order",
                "reference_name": doc.name
            },
            fields=["comment_email", "creation"],
            order_by="creation asc"
        ) %}


        <div class="approval-signatures">

            {% for approval in all_approval %}

                {% if approval.comment_email %}

                    {% set user_data = frappe.db.get_value(
                        "User",
                        approval.comment_email,
                        ["full_name", "email", "email_signature"],
                        as_dict=True
                    ) %}


                    {% if user_data and user_data.email_signature %}

                        <div class="approval-signature">

                            <div class="approval-signature-image">
                                {{ user_data.email_signature }}
                            </div>

                            <div class="approval-user-name">
                                {{ user_data.full_name or approval.comment_email }}
                            </div>

                            <div class="approval-user-email">
                                {{ user_data.email or approval.comment_email }}
                            </div>

                        </div>

                    {% endif %}

                {% endif %}

            {% endfor %}

        </div>

    </div>


</div>


<!-- =========================
     FOOTER
========================== -->

<div {% if print_settings.repeat_header_footer %}id="footer-html" class="visible-pdf"{% endif %}>

    {% if not no_letterhead and footer %}

    <div class="letter-head-footer">
        {{ footer }}
    </div>

    {% endif %}


    {% if print_settings.repeat_header_footer %}

    <p class="text-center page-number visible-pdf">

        {{ _("Page {0} of {1}").format(
            '<span class="page"></span>',
            '<span class="topage"></span>'
        ) }}

    </p>

    {% endif %}

</div>

</div>

{% endfor %}
